class Solution {
    public: string breakPalindrome(string palindrome){
        if(palindrome.size()==1)return "";
        for(int i=0;i<(int)palindrome.size()/2;++i)if(palindrome[i]!='a'){
            palindrome[i]='a';
            return palindrome;
        }
        palindrome.back()='b';
        return palindrome;
    }
};
